        "home.title": "O teu diário de ginásio que nunca sai do teu telemóvel.",
        "home.lead": "Planeia rotinas, regista séries em tempo real e acompanha o teu progresso com gráficos — tudo armazenado de forma privada no teu dispositivo. Sem registo, sem subscrição, funciona offline.",
        "home.cta.openApp": "Abrir a app",
