        "home.feature.privacyTitle": "Os teus dados nunca saem do teu dispositivo",
        "home.feature.privacyBody": "Cada rotina, sessão e medição é guardada no teu navegador. Sem servidor, sem sincronização na nuvem, sem conta — os teus dados de treino são só teus.",
        "home.feature.sessionTitle": "Feita para o ginásio",
        "home.feature.sessionBody": "Inicia uma sessão, completa séries com um toque, recebe notificações de descanso e revê um resumo completo do treino ao terminar — tudo desenhado para usar com uma mão entre séries.",
        "home.feature.progressTitle": "Vê o teu progresso num instante",
        "home.feature.progressBody": "Gráficos leves mostram tendências de peso e repetições ao longo do tempo para cada exercício, incluindo seguimento esquerda/direita para trabalho unilateral. Gráficos de composição corporal estão a um toque.",
        "home.cta.features": "Funcionalidades",
        "home.cta.about": "Como funciona",
        "home.cta.privacy": "Privacidade",
        "features.eyebrow": "Todas as funcionalidades",
        "features.title": "Tudo o que precisas para treinar melhor — nada que não precises.",
        "features.lead": "O Easy Gym Routine Tracker oferece-te um criador de rotinas rápido, seguimento de sessões ao vivo e gráficos de progresso — sem contas, sem anúncios e sem enviar os teus dados para lado nenhum.",
        "features.cta.home": "Início",
        "features.cta.openApp": "Abrir a app",
        "features.cta.privacy": "Privacidade",
        "features.routineBuilder.title": "Criador de rotinas",
        "features.routineBuilder.body": "Cria exercícios, organiza-os em rotinas e configura repetições alvo, pesos e tempos de descanso — sem assistentes complicados.",
        "features.sessionMode.title": "Seguimento de sessão ao vivo",
        "features.sessionMode.body": "Começa um treino, completa séries com um único toque e obtém temporizadores de descanso automáticos. A app guia-te por cada exercício para te focares em levantar.",
        "features.unilateral.title": "Séries unilaterais e bilaterais",
        "features.unilateral.body": "Regista repetições e peso esquerda/direita de forma independente para exercícios de um só braço ou perna, com historial completo para cada lado.",
        "features.historyCharts.title": "Gráficos de progresso",
        "features.historyCharts.body": "Visualiza tendências de peso e repetições ao longo do tempo com gráficos táteis. Deteta estagnações, confirma recordes pessoais e mantém a motivação com feedback visual claro.",
        "features.workoutCalendar.title": "Calendário de treinos",
        "features.workoutCalendar.body": "Consulta a tua frequência de treino num instante com um calendário mensal. Toca em qualquer dia para rever detalhes do treino, séries totais, repetições e volume.",
        "features.workoutSummary.title": "Resumos pós-treino",
        "features.workoutSummary.body": "Após cada sessão, obtém uma análise de séries completadas, repetições totais, volume levantado e novos recordes pessoais — além de comparações divertidas como \"levantaste 3 labradores\".",
        "features.portableExports.title": "Exportações JSON portáteis",
        "features.portableExports.body": "Descarrega as tuas rotinas ou medições corporais num formato JSON estável. Importa-as em qualquer dispositivo — sem necessidade de conta na nuvem.",
        "features.localFirst.title": "100 % local-first",
        "features.localFirst.body": "Todos os dados — rotinas, sessões e medições corporais — ficam apenas no teu dispositivo através do armazenamento do navegador. Nada é enviado para um servidor.",
        "features.profileTracking.title": "Seguimento de composição corporal",
        "features.profileTracking.body": "Regista peso, percentagem de gordura e massa muscular ao longo do tempo. Gráficos de picos diários e um gestor de historial completo ajudam-te a acompanhar mudanças para além da barra.",
        "features.pwa.title": "Funciona offline (PWA)",
        "features.pwa.body": "Instala o Easy Gym Routine Tracker no teu ecrã inicial e usa-o como uma app nativa. Uma vez carregado, funciona sem ligação à internet.",
        "features.notifications.title": "Notificações de descanso",
        "features.notifications.body": "Recebe uma notificação quando o teu tempo de descanso terminar para te focares na recuperação em vez de olhar para o relógio.",
        "privacy.eyebrow": "A tua privacidade",
        "privacy.title": "Sem servidor, sem rastreio, sem conta — os teus dados de treino ficam no teu dispositivo.",
        "privacy.lead": "O Easy Gym Routine Tracker baseia-se numa regra simples: nada sai do teu navegador. Rotinas, sessões, medições corporais e historial são armazenados localmente e nunca enviados para lado nenhum.",
        "privacy.cta.home": "Início",
        "privacy.cta.features": "Funcionalidades",
        "privacy.cta.openApp": "Abrir a app",
        "privacy.whatStored.title": "O que é armazenado",
        "privacy.whatStored.body": "Definições de rotinas, objetivos de séries, descrições de exercícios, historial de sessões e medições corporais são guardados no armazenamento do navegador no teu dispositivo. Nada é enviado para um servidor.",
        "privacy.notRequired.title": "Sem conta necessária",
        "privacy.notRequired.body": "Não é necessária conta de utilizador, e-mail, palavra-passe ou perfil remoto. Abre a app e começa a treinar — é tudo.",
        "privacy.noAnalytics.title": "Sem analíticas nem scripts de rastreio",
        "privacy.noAnalytics.body": "A app não carrega nenhum script de rastreio de terceiros. Não há serviços de analítica, nem píxeis de seguimento, nem SDKs de publicidade. A tua utilização é completamente privada.",
        "privacy.noCookies.title": "Sem cookies",
        "privacy.noCookies.body": "A app não define nenhum cookie. A tua preferência de idioma e dados de treino são armazenados no localStorage do navegador, que nunca é enviado para um servidor automaticamente.",
        "privacy.notifications.title": "As notificações são locais",
        "privacy.notifications.body": "Se permitires notificações, são geradas inteiramente no teu dispositivo para lembretes da sessão. Nenhum dado é enviado para um servidor de notificações.",
        "privacy.exports.title": "Portabilidade de dados",
        "privacy.exports.body": "Exporta rotinas ou medições corporais para um ficheiro JSON portátil a qualquer momento. Os ficheiros importados são processados localmente — nenhum dado é enviado para qualquer servidor.",
        "privacy.localOnly.title": "Os teus dados são privados",
        "privacy.localOnly.body": "A app não tem backend, nem serviço de sincronização, nem contas de utilizador. Cada byte dos teus dados de treino e corporais permanece apenas no armazenamento do teu próprio navegador.",
        "about.eyebrow": "Começa agora",
        "about.title": "Da primeira rotina a recordes pessoais em quatro passos simples.",
        "about.lead": "O Easy Gym Routine Tracker simplifica o fluxo: cria uma vez, treina sempre e vê o teu progresso crescer — tudo sem sair do teu telemóvel.",
        "about.cta.home": "Início",
        "about.cta.openApp": "Experimenta agora",
        "about.cta.features": "Ver todas as funcionalidades",
        "about.step1.title": "1. Cria a tua rotina",
        "about.step1.body": "Adiciona exercícios com repetições alvo, pesos e tempos de descanso. Suporta séries bilaterais e unilaterais (esquerda/direita) para total flexibilidade.",
        "about.step2.title": "2. Inicia uma sessão",
        "about.step2.body": "Toca em \"Começar\" e avança por cada exercício série a série. Regista o que realmente levantaste, recebe alertas de descanso e mantém-te focado no treino.",
        "about.step3.title": "3. Revê o teu progresso",
        "about.step3.body": "Após cada sessão, um resumo mostra volume total, repetições, recordes e comparações divertidas. Os gráficos de historial permitem-te seguir tendências ao longo de semanas e meses.",
        "about.step4.title": "4. Mantém o controlo",
        "about.step4.body": "Exporta rotinas ou dados corporais para JSON a qualquer momento. Importa-os noutro dispositivo ou partilha-os com um amigo — sem conta nem serviço na nuvem.",
        "about.step5.title": "5. Instala no teu telemóvel",
        "about.step5.body": "Adiciona a app ao teu ecrã inicial para acesso instantâneo. Funciona offline e parece uma app nativa — sem descarregar de lojas de apps.",

