        "privacy.noAnalytics.body": "アプリはサードパーティのトラッキングスクリプトを一切読み込みません。分析サービス、ピクセルトラッカー、広告SDKは存在しません。利用状況は完全に監視されません。",
        "privacy.noCookies.title": "クッキーなし",
        "privacy.noCookies.body": "アプリはクッキーを一切使用しません。言語設定とワークアウトデータはブラウザのlocalStorageに保存され、サーバーに自動送信されることはありません。",
        "privacy.notifications.title": "通知もローカル",
        "privacy.notifications.body": "通知を許可した場合、セッション関連のリマインダーとしてデバイス上で完全に生成されます。プッシュサーバーにデータは送信されません。",
        "privacy.exports.title": "データポータビリティ",
        "privacy.exports.body": "ルーティンや体組成データをいつでもポータブルなJSONファイルにエクスポート。インポートファイルはローカルで処理され、サーバーにアップロードされることはありません。",
        "privacy.localOnly.title": "あなたのデータはプライベートに保たれます",
        "privacy.localOnly.body": "アプリにはバックエンド、同期サービス、ユーザーアカウントがありません。ワークアウトと体組成データの全バイトが、あなた自身のブラウザストレージにのみ残ります。",
        "about.eyebrow": "はじめに",
        "about.title": "最初のルーティンから自己ベストまで、4つのシンプルなステップで。",
        "about.lead": "Easy Gym Routine Trackerはワークフローを最小限に：一度組んだら繰り返しトレーニングし、進捗の成長を見守る — すべてスマホだけで完結。",
        "about.cta.home": "ホーム",
        "about.cta.openApp": "今すぐ試す",
        "about.cta.features": "全機能を見る",
        "about.step1.title": "1. ルーティンを組む",
        "about.step1.body": "目標レップ数、重量、休憩時間付きのエクササイズを追加。バイラテラルとユニラテラル（左右）セットの両方に対応し、完全な柔軟性を提供。",
        "about.step2.title": "2. セッションを開始",
        "about.step2.body": "\"開始\"をタップしてセットごとに各エクササイズを進めます。実際に挙げた重量を記録し、休憩タイマーアラートを受け取り、ワークアウトに集中。",
        "about.step3.title": "3. 進捗を確認",
        "about.step3.body": "各セッション後にサマリーで合計ボリューム、レップ数、PR、楽しい比較を表示。履歴チャートで数週間・数ヶ月の推移を追跡。",
        "about.step4.title": "4. 主導権を握る",
        "about.step4.body": "ルーティンや体組成データをいつでもJSONにエクスポート。別のデバイスにインポートしたり友人と共有 — アカウントやクラウドサービス不要。",
        "about.step5.title": "5. スマホにインストール",
        "about.step5.body": "ホーム画面に追加すればすぐにアクセス可能。オフラインで動作し、ネイティブアプリのような使い心地 — アプリストアからのダウンロード不要。",

