        "privacy.whatStored.body": "训练计划定义、组数目标、动作描述、训练历史和身体数据全部保存在你设备的浏览器存储中。绝不会发送到任何服务器。",
        "privacy.notRequired.title": "无需账号",
        "privacy.notRequired.body": "不需要用户账号、邮箱、密码或远程档案。打开应用，开始训练 — 就这么简单。",
        "privacy.noAnalytics.title": "无分析或追踪脚本",
        "privacy.noAnalytics.body": "应用不加载任何第三方追踪脚本。没有分析服务、没有像素追踪器、没有广告 SDK。你的使用完全不被监控。",
        "privacy.noCookies.title": "无 Cookie",
        "privacy.noCookies.body": "应用不设置任何 Cookie。你的语言偏好和训练数据存储在浏览器 localStorage 中，永远不会自动发送到服务器。",
        "privacy.notifications.title": "通知保持本地",
        "privacy.notifications.body": "如果你允许通知，它们完全在你的设备上生成，用于训练相关提醒。不会向推送服务器发送任何数据。",
        "privacy.exports.title": "数据可移植性",
        "privacy.exports.body": "随时将训练计划或身体数据导出为便携式 JSON 文件。导入文件在本地处理 — 不会上传到任何服务器。",
        "privacy.localOnly.title": "你的数据保持私密",
        "privacy.localOnly.body": "应用没有后端、没有同步服务、没有用户账号。你的训练和身体数据的每一个字节都只保留在你自己的浏览器存储中。",
        "about.eyebrow": "开始使用",
        "about.title": "从第一个计划到个人纪录，只需四个简单步骤。",
        "about.lead": "Easy Gym Routine Tracker 将流程精简到极致：创建一次，反复训练，见证进步增长 — 一切尽在手机中完成。",
        "about.cta.home": "首页",
        "about.cta.openApp": "立即体验",
        "about.cta.features": "查看全部功能",
        "about.step1.title": "1. 创建你的训练计划",
        "about.step1.body": "添加带有目标次数、重量和休息时间的动作。同时支持双侧和单侧（左/右）训练组，提供完全的灵活性。",
        "about.step2.title": "2. 开始训练",
        "about.step2.body": "点击\"开始\"，逐组完成每个动作。记录实际举起的重量，接收休息计时提醒，专注于训练本身。",
        "about.step3.title": "3. 查看你的进步",
        "about.step3.body": "每次训练后，总结显示总训练量、次数、个人纪录和有趣的对比。历史图表让你追踪数周和数月的趋势。",
        "about.step4.title": "4. 掌控你的数据",
        "about.step4.body": "随时将训练计划或身体数据导出为 JSON。在其他设备上导入或与朋友分享 — 无需账号或云服务。",
        "about.step5.title": "5. 安装到手机",
        "about.step5.body": "添加到主屏幕即可即时访问。离线可用，体验如原生应用 — 无需从应用商店下载。",

