        "home.lead": "रूटीन बनाएँ, सेट्स रियल टाइम में लॉग करें, और चार्ट्स से अपनी प्रगति ट्रैक करें — सब कुछ आपके डिवाइस पर निजी रूप से सुरक्षित। न साइन-अप, न सब्सक्रिप्शन, ऑफ़लाइन भी चलता है।",
