        "home.feature.privacyBody": "Каждая программа, тренировка и замер хранятся в вашем браузере. Нет сервера, нет облачной синхронизации, аккаунт не нужен — ваши тренировочные данные принадлежат только вам.",
        "home.feature.sessionTitle": "Создано для тренажёрного зала",
