        "about.step1.title": "1. Создайте программу",
        "about.step1.body": "Добавьте упражнения с целевыми повторениями, весами и периодами отдыха. Поддерживаются билатеральные и унилатеральные (лево/право) подходы для полной гибкости.",
        "about.step2.title": "2. Начните тренировку",
        "about.step2.body": "Нажмите «Старт» и выполняйте каждое упражнение подход за подходом. Записывайте реально поднятый вес, получайте оповещения таймера отдыха и оставайтесь сосредоточенными.",
        "about.step3.title": "3. Оцените прогресс",
        "about.step3.body": "После каждой тренировки отчёт показывает общий объём, повторения, личные рекорды и забавные сравнения. Графики истории позволяют отслеживать тенденции за недели и месяцы.",
        "about.step4.title": "4. Контролируйте свои данные",
        "about.step4.body": "Экспортируйте программы или физические данные в JSON в любое время. Импортируйте их на другом устройстве или поделитесь с другом — без аккаунта и облачного сервиса.",
