        "home.feature.privacyTitle": "I tuoi dati non lasciano mai il dispositivo",
        "home.feature.privacyBody": "Ogni scheda, sessione e misurazione è archiviata nel tuo browser. Nessun server, nessuna sincronizzazione cloud, nessun account richiesto — i tuoi dati di allenamento sono solo tuoi.",
        "home.feature.sessionTitle": "Progettato per la sala pesi",
        "home.feature.sessionBody": "Avvia una sessione, completa le serie con un tocco, ricevi notifiche del timer di riposo e rivedi un riepilogo completo dell'allenamento a fine sessione — tutto pensato per l'uso con una mano tra una serie e l'altra.",
        "home.feature.progressTitle": "I tuoi progressi a colpo d'occhio",
        "home.feature.progressBody": "Grafici leggeri mostrano l'andamento di pesi e ripetizioni nel tempo per ogni esercizio, incluso il tracciamento destro/sinistro per il lavoro unilaterale. I grafici di composizione corporea sono a portata di tocco.",
        "home.cta.features": "Funzionalità",
        "home.cta.about": "Come funziona",
        "home.cta.privacy": "Privacy",
        "features.eyebrow": "Tutte le funzionalità",
        "features.title": "Tutto ciò che serve per allenarti meglio — niente di superfluo.",
        "features.lead": "Easy Gym Routine Tracker ti offre un costruttore di schede veloce, tracciamento sessioni in tempo reale e grafici di progresso — senza account, pubblicità o invio dei tuoi dati.",
        "features.cta.home": "Home",
        "features.cta.openApp": "Apri l'app",
        "features.cta.privacy": "Privacy",
        "features.routineBuilder.title": "Costruttore di schede",
        "features.routineBuilder.body": "Crea esercizi, organizzali in schede e configura ripetizioni target, pesi e tempi di riposo — nessun wizard complicato.",
        "features.sessionMode.title": "Tracciamento sessione in tempo reale",
        "features.sessionMode.body": "Inizia un allenamento, completa le serie con un singolo tocco e ottieni timer di riposo automatici. L'app ti guida attraverso ogni esercizio così puoi concentrarti sul sollevamento.",
        "features.unilateral.title": "Serie unilaterali e bilaterali",
        "features.unilateral.body": "Traccia ripetizioni e peso per destro/sinistro in modo indipendente per esercizi a un braccio o una gamba, con cronologia completa per ogni lato.",
        "features.historyCharts.title": "Grafici di progresso",
        "features.historyCharts.body": "Visualizza l'andamento di pesi e ripetizioni nel tempo con grafici touch-friendly. Individua i plateau, conferma i PR e resta motivato con un feedback visivo chiaro.",
        "features.workoutCalendar.title": "Calendario allenamenti",
        "features.workoutCalendar.body": "Verifica la frequenza di allenamento a colpo d'occhio con un calendario mensile. Tocca un giorno qualsiasi per i dettagli dell'allenamento, serie totali, ripetizioni e volume.",
        "features.workoutSummary.title": "Riepiloghi post-allenamento",
        "features.workoutSummary.body": "Dopo ogni sessione, ottieni un resoconto di serie completate, ripetizioni totali, volume sollevato e nuovi record personali — più confronti divertenti come \"hai sollevato 3 labrador\".",
        "features.portableExports.title": "Esportazione JSON portatile",
        "features.portableExports.body": "Scarica le tue schede o le misurazioni corporee in un formato JSON stabile. Importale su qualsiasi dispositivo — nessun account cloud necessario.",
        "features.localFirst.title": "100 % local-first",
        "features.localFirst.body": "Tutti i dati — schede, sessioni e misurazioni corporee — restano solo sul tuo dispositivo tramite lo storage del browser. Nulla viene mai inviato a un server.",
        "features.profileTracking.title": "Monitoraggio composizione corporea",
        "features.profileTracking.body": "Registra peso, massa grassa e massa muscolare nel tempo. Grafici dei picchi giornalieri e un gestore completo dello storico ti aiutano a monitorare i cambiamenti oltre il bilanciere.",
        "features.pwa.title": "Funziona offline (PWA)",
        "features.pwa.body": "Installa Easy Gym Routine Tracker sulla schermata Home e usalo come un'app nativa. Una volta caricato, funziona senza connessione internet.",
        "features.notifications.title": "Notifiche timer di riposo",
        "features.notifications.body": "Ricevi una notifica push quando il tuo tempo di riposo finisce, così puoi concentrarti sul recupero invece di fissare l'orologio.",
        "privacy.eyebrow": "La tua privacy",
        "privacy.title": "Nessun server, nessun tracciamento, nessun account — i tuoi dati di allenamento restano sul tuo dispositivo.",
        "privacy.lead": "Easy Gym Routine Tracker è costruito su una regola semplice: nulla esce dal tuo browser. Schede, sessioni, misurazioni corporee e cronologia sono archiviate localmente e non vengono mai inviate da nessuna parte.",
        "privacy.cta.home": "Home",
        "privacy.cta.features": "Funzionalità",
        "privacy.cta.openApp": "Apri l'app",
        "privacy.whatStored.title": "Cosa viene archiviato",
        "privacy.whatStored.body": "Definizioni delle schede, obiettivi delle serie, descrizioni degli esercizi, cronologia delle sessioni e misurazioni corporee — tutto salvato nello storage del browser sul tuo dispositivo. Nulla viene mai inviato a un server.",
        "privacy.notRequired.title": "Nessun account richiesto",
        "privacy.notRequired.body": "Non servono account utente, email, password o profilo remoto. Apri l'app e inizia ad allenarti — tutto qui.",
        "privacy.noAnalytics.title": "Nessun script di analisi o tracciamento",
        "privacy.noAnalytics.body": "L'app non carica nessuno script di tracciamento di terze parti. Nessun servizio di analisi, nessun pixel tracker, nessun SDK pubblicitario. Il tuo utilizzo è completamente non monitorato.",
        "privacy.noCookies.title": "Nessun cookie",
        "privacy.noCookies.body": "L'app non imposta alcun cookie. La tua preferenza linguistica e i dati di allenamento sono archiviati nel localStorage del browser, che non viene mai inviato automaticamente a un server.",
        "privacy.notifications.title": "Le notifiche restano locali",
        "privacy.notifications.body": "Se consenti le notifiche, vengono generate interamente sul tuo dispositivo per i promemoria legati alla sessione. Nessun dato viene inviato a un server push.",
        "privacy.exports.title": "Portabilità dei dati",
        "privacy.exports.body": "Esporta schede o misurazioni corporee in un file JSON portatile in qualsiasi momento. I file importati vengono elaborati localmente — nessun dato viene caricato su alcun server.",
        "privacy.localOnly.title": "I tuoi dati restano privati",
        "privacy.localOnly.body": "L'app non ha backend, servizio di sincronizzazione né account utente. Ogni byte dei tuoi dati di allenamento e corporei rimane solo nello storage del tuo browser.",
        "about.eyebrow": "Inizia subito",
        "about.title": "Dalla prima scheda ai record personali in quattro semplici passaggi.",
        "about.lead": "Easy Gym Routine Tracker mantiene il flusso di lavoro essenziale: crea una volta, allenati regolarmente e guarda i tuoi progressi crescere — tutto senza lasciare il telefono.",
        "about.cta.home": "Home",
        "about.cta.openApp": "Prova ora",
        "about.cta.features": "Tutte le funzionalità",
        "about.step1.title": "1. Crea la tua scheda",
        "about.step1.body": "Aggiungi esercizi con ripetizioni target, pesi e tempi di riposo. Supporta sia serie bilaterali che unilaterali (destro/sinistro) per la massima flessibilità.",
        "about.step2.title": "2. Avvia una sessione",
        "about.step2.body": "Tocca \"Inizia\" e affronta ogni esercizio serie per serie. Registra ciò che hai effettivamente sollevato, ricevi avvisi del timer di riposo e resta concentrato sull'allenamento.",
        "about.step3.title": "3. Rivedi i tuoi progressi",
        "about.step3.body": "Dopo ogni sessione, un riepilogo mostra volume totale, ripetizioni, PR e confronti divertenti. I grafici storici ti permettono di seguire i trend per settimane e mesi.",
        "about.step4.title": "4. Mantieni il controllo",
        "about.step4.body": "Esporta schede o dati corporei in JSON in qualsiasi momento. Importali su un altro dispositivo o condividili con un amico — nessun account o servizio cloud necessario.",
        "about.step5.title": "5. Installalo sul telefono",
        "about.step5.body": "Aggiungi l'app alla schermata Home per un accesso immediato. Funziona offline e si comporta come un'app nativa — nessun download dall'app store richiesto.",

