        "home.feature.privacyTitle": "Je gegevens verlaten nooit je toestel",
        "home.feature.privacyBody": "Elk schema, elke sessie en elke meting wordt in je browser opgeslagen. Geen server, geen cloudsync, geen account nodig — je trainingsgegevens zijn alleen van jou.",
        "home.feature.sessionTitle": "Gemaakt voor op de gymvloer",
        "home.feature.sessionBody": "Start een sessie, rond sets af met één tik, ontvang rusttimer-meldingen en bekijk een volledig trainingsoverzicht als je klaar bent — ontworpen voor gebruik met één hand tussen sets door.",
        "home.feature.progressTitle": "Bekijk je voortgang in één oogopslag",
