        "home.cta.features": "Functies",
        "home.cta.about": "Hoe het werkt",
        "home.cta.privacy": "Privacy",
        "features.eyebrow": "Alle functies",
        "features.title": "Alles wat je nodig hebt om slimmer te trainen — niets wat je niet nodig hebt.",
        "features.lead": "Easy Gym Routine Tracker biedt een snelle schema-builder, live sessietracking en voortgangsgrafieken — zonder accounts, advertenties of het versturen van je gegevens.",
        "features.cta.home": "Home",
        "features.cta.openApp": "Open de app",
        "features.cta.privacy": "Privacy",
        "features.routineBuilder.title": "Schema-builder",
        "features.routineBuilder.body": "Maak oefeningen, organiseer ze in schema's en stel doelherhalingen, gewichten en rustperiodes in — geen ingewikkelde wizard nodig.",
        "features.sessionMode.title": "Live sessietracking",
        "features.sessionMode.body": "Start een workout, rond sets af met één tik en krijg automatische rusttimers. De app begeleidt je door elke oefening zodat jij je op het tillen kunt richten.",
        "features.unilateral.title": "Unilaterale & bilaterale sets",
        "features.unilateral.body": "Volg links/rechts herhalingen en gewicht apart voor eenarmige of eenbenige oefeningen, met volledige historie per zijde.",
        "features.historyCharts.title": "Voortgangsgrafieken",
        "features.historyCharts.body": "Visualiseer gewichts- en herhalingstrends met aanraakvriendelijke grafieken. Herken plateaus, bevestig PR's en blijf gemotiveerd met duidelijke visuele feedback.",
        "features.workoutCalendar.title": "Trainingskalender",
        "features.workoutCalendar.body": "Bekijk je trainingsfrequentie in één oogopslag met een maandkalender. Tik op een dag om workoutdetails, totale sets, herhalingen en volume te bekijken.",
        "features.workoutSummary.title": "Samenvattingen na de workout",
        "features.workoutSummary.body": "Na elke sessie krijg je een overzicht van voltooide sets, totale herhalingen, getild volume en nieuwe persoonlijke records — plus leuke vergelijkingen zoals \"je hebt 3 labradors getild\".",
        "features.portableExports.title": "Draagbare JSON-exports",
        "features.portableExports.body": "Download je schema's of lichaamsmetingen in een stabiel JSON-formaat. Importeer ze op elk apparaat — geen cloudaccount nodig.",
        "features.localFirst.title": "100 % local-first",
        "features.localFirst.body": "Alle gegevens — schema's, sessies en lichaamsmetingen — blijven uitsluitend op je toestel via browseropslag. Er wordt nooit iets naar een server gestuurd.",
        "features.profileTracking.title": "Lichaamssamenstelling bijhouden",
        "features.profileTracking.body": "Log gewicht, vetpercentage en spiermassa in de loop van de tijd. Dagelijkse piekgrafieken en een volledig historiebeheer helpen je veranderingen buiten de halter te volgen.",
        "features.pwa.title": "Werkt offline (PWA)",
        "features.pwa.body": "Installeer Easy Gym Routine Tracker op je startscherm en gebruik het als een native app. Eenmaal geladen werkt het zonder internetverbinding.",
        "features.notifications.title": "Rusttimer-meldingen",
        "features.notifications.body": "Ontvang een pushmelding wanneer je rustperiode voorbij is, zodat je je op herstel kunt richten in plaats van op een klok te kijken.",
        "privacy.eyebrow": "Jouw privacy",
        "privacy.title": "Geen server, geen tracking, geen account — je workoutgegevens blijven op je toestel.",
        "privacy.lead": "Easy Gym Routine Tracker is gebouwd rond één simpele regel: niets verlaat je browser. Schema's, sessies, lichaamsmetingen en historie worden lokaal opgeslagen en nooit ergens naartoe gestuurd.",
        "privacy.cta.home": "Home",
        "privacy.cta.features": "Functies",
        "privacy.cta.openApp": "Open de app",
        "privacy.whatStored.title": "Wat wordt opgeslagen",
        "privacy.whatStored.body": "Schemadefinities, setdoelen, oefeningbeschrijvingen, sessiegeschiedenis en lichaamsmetingen worden allemaal opgeslagen in de browseropslag op je toestel. Er wordt nooit iets naar een server gestuurd.",
        "privacy.notRequired.title": "Geen account nodig",
        "privacy.notRequired.body": "Geen gebruikersaccount, e-mail, wachtwoord of extern profiel nodig. Open de app en begin met trainen — dat is alles.",
        "privacy.noAnalytics.title": "Geen analytics of trackingscripts",
        "privacy.noAnalytics.body": "De app laadt nul trackingscripts van derden. Er zijn geen analyticsdiensten, geen pixeltrackers en geen reclame-SDK's. Je gebruik wordt volledig ongemonitord.",
        "privacy.noCookies.title": "Geen cookies",
        "privacy.noCookies.body": "De app plaatst geen cookies. Je taalvoorkeur en workoutgegevens worden opgeslagen in browser-localStorage, die nooit automatisch naar een server wordt gestuurd.",
        "privacy.notifications.title": "Meldingen blijven lokaal",
        "privacy.notifications.body": "Als je meldingen toestaat, worden ze volledig op je toestel gegenereerd voor sessiegerelateerde herinneringen. Er worden geen gegevens naar een pushserver gestuurd.",
        "privacy.exports.title": "Gegevensportabiliteit",
        "privacy.exports.body": "Exporteer schema's of lichaamsmetingen op elk moment naar een draagbaar JSON-bestand. Importbestanden worden lokaal verwerkt — er worden geen gegevens naar een server geüpload.",
        "privacy.localOnly.title": "Je gegevens blijven privé",
        "privacy.localOnly.body": "De app heeft geen backend, geen synchronisatiedienst en geen gebruikersaccounts. Elke byte van je workout- en lichaamsgegevens blijft uitsluitend in je eigen browseropslag.",
        "about.eyebrow": "Aan de slag",
        "about.title": "Van eerste schema tot persoonlijke records in vier simpele stappen.",
        "about.lead": "Easy Gym Routine Tracker houdt de workflow minimaal: bouw één keer, train herhaaldelijk en zie je voortgang groeien — zonder je telefoon te verlaten.",
        "about.cta.home": "Home",
        "about.cta.openApp": "Probeer het nu",
        "about.cta.features": "Bekijk alle functies",
        "about.step1.title": "1. Bouw je schema",
        "about.step1.body": "Voeg oefeningen toe met doelherhalingen, gewichten en rustperiodes. Ondersteunt zowel bilaterale als unilaterale (links/rechts) sets voor volledige flexibiliteit.",
        "about.step2.title": "2. Start een sessie",
        "about.step2.body": "Tik op \"Start\" en werk door elke oefening set voor set. Log wat je daadwerkelijk hebt getild, ontvang rusttimer-meldingen en blijf gefocust op de workout.",
        "about.step3.title": "3. Bekijk je voortgang",
        "about.step3.body": "Na elke sessie toont een samenvatting het totale volume, herhalingen, PR's en leuke vergelijkingen. Historiegrafieken laten je trends over weken en maanden volgen.",
        "about.step4.title": "4. Houd de controle",
        "about.step4.body": "Exporteer schema's of lichaamsgegevens op elk moment naar JSON. Importeer ze op een ander apparaat of deel ze met een vriend — geen account of clouddienst nodig.",
        "about.step5.title": "5. Installeer op je telefoon",
        "about.step5.body": "Voeg de app toe aan je startscherm voor directe toegang. Hij werkt offline en voelt als een native app — geen download uit de app store nodig.",

