        "home.eyebrow": "Darmowy i prywatny tracker treningów",
        "home.title": "Twój dziennik treningowy, który nigdy nie opuszcza telefonu.",
        "home.lead": "Planuj schematy, zapisuj serie w czasie rzeczywistym i śledź postępy na wykresach — wszystko przechowywane prywatnie na Twoim urządzeniu. Bez rejestracji, bez subskrypcji, działa offline.",
