        "home.feature.privacyTitle": "Verileriniz cihazınızdan asla ayrılmaz",
        "home.feature.privacyBody": "Her rutin, seans ve ölçüm tarayıcınızda saklanır. Sunucu yok, bulut senkronizasyonu yok, hesap gerekmez — antrenman verileriniz yalnızca sizindir.",
        "home.feature.sessionTitle": "Spor salonu için tasarlandı",
        "home.feature.sessionBody": "Bir seans başlat, setleri tek dokunuşla tamamla, dinlenme süresi bildirimleri al ve bitirdiğinde tam bir antrenman özeti incele — setler arasında tek elle kullanım için tasarlandı.",
        "home.feature.progressTitle": "İlerlemenizi bir bakışta görün",
        "home.feature.progressBody": "Hafif grafikler her egzersiz için ağırlık ve tekrar trendlerini gösterir; tek taraflı çalışma için sol/sağ takibi dahil. Vücut kompozisyonu grafikleri bir dokunuş uzağınızda.",
        "home.cta.features": "Özellikler",
