        "home.cta.privacy": "Gizlilik",
        "features.eyebrow": "Tüm özellikler",
        "features.title": "Daha akıllı antrenman için ihtiyacın olan her şey — ihtiyacın olmayan hiçbir şey.",
        "features.lead": "Easy Gym Routine Tracker hızlı bir rutin oluşturucu, canlı seans takibi ve ilerleme grafikleri sunar — hesap, reklam veya veri gönderimi olmadan.",
        "features.cta.home": "Ana sayfa",
        "features.cta.openApp": "Uygulamayı aç",
        "features.cta.privacy": "Gizlilik",
        "features.routineBuilder.title": "Rutin oluşturucu",
        "features.routineBuilder.body": "Egzersizler oluştur, rutinler halinde düzenle ve hedef tekrarları, ağırlıkları ve dinlenme sürelerini ayarla — karmaşık sihirbaz gerekmez.",
        "features.sessionMode.title": "Canlı seans takibi",
        "features.sessionMode.body": "Antrenmanı başlat, setleri tek dokunuşla tamamla ve otomatik dinlenme sayaçları al. Uygulama seni her egzersizde yönlendirir, böylece kaldırmaya odaklanabilirsin.",
        "features.unilateral.title": "Tek taraflı ve çift taraflı setler",
        "features.unilateral.body": "Tek kol veya tek bacak egzersizleri için sol/sağ tekrar ve ağırlığı bağımsız olarak takip et; her taraf için tam geçmiş.",
        "features.historyCharts.title": "İlerleme grafikleri",
        "features.historyCharts.body": "Dokunmatik dostu grafiklerle ağırlık ve tekrar trendlerini görselleştir. Platolari tespit et, kişisel rekorları onayla ve net görsel geri bildirimle motivasyonunu koru.",
        "features.workoutCalendar.title": "Antrenman takvimi",
        "features.workoutCalendar.body": "Aylık takvimle antrenman sıklığını bir bakışta gör. Herhangi bir güne dokun ve antrenman detaylarını, toplam set, tekrar ve hacmi incele.",
        "features.workoutSummary.title": "Antrenman sonrası özetler",
        "features.workoutSummary.body": "Her seanstan sonra tamamlanan setler, toplam tekrarlar, kaldırılan hacim ve yeni kişisel rekorların dökümünü al — artı \"3 Labrador kaldırdın\" gibi eğlenceli karşılaştırmalar.",
        "features.portableExports.title": "Taşınabilir JSON dışa aktarımları",
        "features.portableExports.body": "Rutinlerini veya vücut ölçümlerini sabit bir JSON formatında indir. Herhangi bir cihazda içe aktar — bulut hesabı gerekmez.",
        "features.localFirst.title": "% 100 yerel öncelikli",
        "features.localFirst.body": "Tüm veriler — rutinler, seanslar ve vücut ölçümleri — yalnızca cihazınızda tarayıcı depolaması aracılığıyla kalır. Hiçbir şey bir sunucuya gönderilmez.",
        "features.profileTracking.title": "Vücut kompozisyonu takibi",
        "features.profileTracking.body": "Zaman içinde kilo, vücut yağı ve kas kütlesini kaydet. Günlük zirve grafikleri ve tam geçmiş yöneticisi, halter dışındaki değişimleri takip etmene yardımcı olur.",
        "features.pwa.title": "Çevrimdışı çalışır (PWA)",
        "features.pwa.body": "Easy Gym Routine Tracker'ı ana ekranına kur ve yerel bir uygulama gibi kullan. Yüklendikten sonra internet bağlantısı olmadan çalışır.",
        "features.notifications.title": "Dinlenme süresi bildirimleri",
        "features.notifications.body": "Dinlenme süren bittiğinde bir push bildirimi al; böylece saate bakmak yerine toparlanmana odaklanabilirsin.",
        "privacy.eyebrow": "Gizliliğiniz",
        "privacy.title": "Sunucu yok, takip yok, hesap yok — antrenman verileriniz cihazınızda kalır.",
        "privacy.lead": "Easy Gym Routine Tracker basit bir kurala göre geliştirildi: hiçbir şey tarayıcınızı terk etmez. Rutinler, seanslar, vücut ölçümleri ve geçmiş yerel olarak saklanır ve asla hiçbir yere gönderilmez.",
        "privacy.cta.home": "Ana sayfa",
        "privacy.cta.features": "Özellikler",
        "privacy.cta.openApp": "Uygulamayı aç",
        "privacy.whatStored.title": "Ne saklanır",
        "privacy.whatStored.body": "Rutin tanımları, set hedefleri, egzersiz açıklamaları, seans geçmişi ve vücut ölçümleri — tümü cihazınızdaki tarayıcı depolamasına kaydedilir. Hiçbir şey bir sunucuya gönderilmez.",
        "privacy.notRequired.title": "Hesap gerekmez",
        "privacy.notRequired.body": "Kullanıcı hesabı, e-posta, şifre veya uzak profil gerekmez. Uygulamayı aç ve antrenmana başla — hepsi bu.",
        "privacy.noAnalytics.title": "Analitik veya takip scripti yok",
        "privacy.noAnalytics.body": "Uygulama sıfır üçüncü taraf takip scripti yükler. Analitik hizmeti yok, piksel takipçisi yok, reklam SDK'sı yok. Kullanımınız tamamen izlenmez.",
        "privacy.noCookies.title": "Çerez yok",
        "privacy.noCookies.body": "Uygulama hiçbir çerez ayarlamaz. Dil tercihiniz ve antrenman verileriniz tarayıcı localStorage'ında saklanır; bu veriler asla otomatik olarak bir sunucuya gönderilmez.",
        "privacy.notifications.title": "Bildirimler yerel kalır",
        "privacy.notifications.body": "Bildirimlere izin verirseniz, bunlar seansla ilgili hatırlatıcılar için tamamen cihazınızda oluşturulur. Hiçbir veri bir push sunucusuna gönderilmez.",
        "privacy.exports.title": "Veri taşınabilirliği",
        "privacy.exports.body": "Rutinleri veya vücut ölçümlerini istediğiniz zaman taşınabilir bir JSON dosyasına dışa aktarın. İçe aktarma dosyaları yerel olarak işlenir — hiçbir veri bir sunucuya yüklenmez.",
        "privacy.localOnly.title": "Verileriniz gizli kalır",
        "privacy.localOnly.body": "Uygulamanın arka ucu, senkronizasyon hizmeti ve kullanıcı hesabı yoktur. Antrenman ve vücut verilerinizin her baytı yalnızca kendi tarayıcı depolamanızda kalır.",
        "about.eyebrow": "Başlayın",
        "about.title": "İlk rutinden kişisel rekorlara dört basit adımda.",
        "about.lead": "Easy Gym Routine Tracker iş akışını minimal tutar: bir kez oluştur, tekrar tekrar antrenman yap ve ilerlemenin büyümesini izle — telefonundan ayrılmadan.",
        "about.cta.home": "Ana sayfa",
        "about.cta.openApp": "Şimdi dene",
        "about.cta.features": "Tüm özellikleri gör",
        "about.step1.title": "1. Rutinini oluştur",
        "about.step1.body": "Hedef tekrar, ağırlık ve dinlenme süreleriyle egzersizler ekle. Tam esneklik için hem çift taraflı hem de tek taraflı (sol/sağ) setleri destekler.",
        "about.step2.title": "2. Seans başlat",
        "about.step2.body": "\"Başla\"ya dokun ve her egzersizi set set tamamla. Gerçekte kaldırdığını kaydet, dinlenme süresi uyarıları al ve antrenmana odaklan.",
        "about.step3.title": "3. İlerlemenizi inceleyin",
        "about.step3.body": "Her seanstan sonra bir özet toplam hacmi, tekrarları, kişisel rekorları ve eğlenceli karşılaştırmaları gösterir. Geçmiş grafikleri haftalık ve aylık trendleri takip etmenizi sağlar.",
        "about.step4.title": "4. Kontrolü elinizde tutun",
        "about.step4.body": "Rutinleri veya vücut verilerini istediğiniz zaman JSON olarak dışa aktarın. Başka bir cihazda içe aktarın veya arkadaşınızla paylaşın — hesap veya bulut hizmeti gerekmez.",
        "about.step5.title": "5. Telefonunuza kurun",
        "about.step5.body": "Anında erişim için uygulamayı ana ekranınıza ekleyin. Çevrimdışı çalışır ve yerel bir uygulama gibi hissettirir — uygulama mağazasından indirmeye gerek yok.",

